async function buildArticle(doc) {
  const { projectDeckToProse: projectDeckToProse2 } = await Promise.resolve().then(() => (init_prose_projection(), prose_projection_exports));
  const sections = [...doc.querySelectorAll("section[data-lattice-slide]")];
  const { articleHtml, toc } = projectDeckToProse2(sections);
  const tocHtml = toc.map((t) => `<a href="#${t.id}"${t.level === 2 ? ' class="lp-lvl2"' : ""}>${escapeText(t.text)}</a>`).join("\n");
  return { article: articleHtml, toc: tocHtml };
}
